CREATE FUNCTION public.pdc_monitor_authenticated_uid514_claim_scope_684(p_gateway text,p_claim_token uuid,p_intake_id uuid,p_attachment_id uuid,p_parent_hash text,p_attachment_hash text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,auth,extensions AS $scope$
DECLARE i public.ai_email_intake%rowtype; m public.monitored_mailboxes%rowtype; a public.ai_email_attachments%rowtype; z public.pdc_uid514_recovery_authorizations_257%rowtype; s public.pdc_uid514_attachment_selection_673%rowtype; c public.pdc_authenticated_provider_import_agentic_compatibility_controls_684%rowtype; ok boolean:=false;
BEGIN
 IF NOT public.pdc_authenticated_provider_import_agentic_compatibility_enabled_684() OR NOT public.pdc_monitor_authenticated_active_scope_674(p_gateway) THEN RETURN jsonb_build_object('ok',false,'code','authenticated_uid514_scope_required'); END IF;
 SELECT * INTO c FROM public.pdc_authenticated_provider_import_agentic_compatibility_controls_684 WHERE singleton AND enabled;
 SELECT * INTO i FROM public.ai_email_intake WHERE id=p_intake_id AND provider_uid='imap_uid:514' AND source_hash='440d174b6e1994fbb1afb9c285f068cb62b130f541ebaa834d590f44bdbec280' AND status='processing' AND locked_by=auth.uid() AND claim_token=p_claim_token AND gateway_instance_id=p_gateway AND locked_at>=clock_timestamp()-interval '10 minutes';
 SELECT * INTO m FROM public.monitored_mailboxes WHERE id=i.monitored_mailbox_id AND id=c.mailbox_id AND active AND mailbox_key=c.mailbox_key AND lower(mailbox_address)=c.mailbox_address AND lower(provider)=c.provider AND test_mode;
 SELECT * INTO z FROM public.pdc_uid514_recovery_authorizations_257 WHERE recovery_event_id=25751401 AND intake_id=p_intake_id AND parent_source_hash=p_parent_hash AND mailbox_uidvalidity=1 AND mailbox_uid=514 AND qualifying_attachment_sha256=c.job_card_sha256 AND attachment_count=7;
 SELECT * INTO s FROM public.pdc_uid514_attachment_selection_673 WHERE recovery_event_id=25751401 AND intake_id=p_intake_id AND parent_source_hash=p_parent_hash AND observed_mime_part_count=7 AND retained_authenticated_attachment_count=4 AND all_mime_parts_retained AND qualifying_attachment_sha256=c.job_card_sha256;
 SELECT * INTO a FROM public.ai_email_attachments WHERE id=p_attachment_id AND intake_id=p_intake_id AND source_hash=p_attachment_hash AND source_hash=c.job_card_sha256 AND content_type='application/pdf' AND file_name='J139125482 - _13016925.pdf' AND size_bytes=72551 AND storage_path='pdc-email-intake-private/9a8f412ec5c9e108817da26b20993fa0a5e61a54f7ac983673c1ef9e2d8af8f4/J139125482 - _13016925.pdf';
 ok:=i.id IS NOT NULL AND m.id IS NOT NULL AND z.recovery_event_id IS NOT NULL AND s.selection_id IS NOT NULL AND a.id IS NOT NULL AND p_parent_hash=c.parent_source_hash AND p_gateway=c.gateway_instance_id AND p_intake_id=z.intake_id AND p_attachment_id=s.job_card_attachment_id AND NOT c.task_enabled AND NOT c.mailbox_contacted AND NOT c.uid514_processed AND NOT c.production_writes;
 IF NOT ok THEN RETURN jsonb_build_object('ok',false,'code','authenticated_uid514_scope_required'); END IF;
 RETURN jsonb_build_object('ok',true,'code','authenticated_uid514_scope_verified','actor_id',auth.uid(),'actor_email',c.actor_email,'jwt_role',c.jwt_role,'server_application_role',c.server_application_role,'gateway_instance_id',c.gateway_instance_id,'release_name',c.release_name,'source_sha',c.source_sha,'manifest_sha256',c.manifest_sha256,'planner_sha256',c.planner_sha256,'trust_receipt_sha256',c.trust_receipt_sha256,'mailbox_id',c.mailbox_id,'recovery_event_id',c.recovery_event_id,'intake_id',i.id,'attachment_id',a.id,'parent_source_hash',c.parent_source_hash,'attachment_source_hash',a.source_hash,'observed_mime_part_count',7,'retained_authenticated_attachment_count',4,'all_mime_parts_retained',true,'task_enabled',false,'mailbox_contacted',false,'uid514_processed',false,'production_writes',false);
EXCEPTION WHEN others THEN RETURN jsonb_build_object('ok',false,'code','authenticated_uid514_scope_required');
END $scope$;

CREATE FUNCTION public.pdc_authenticated_provider_import_agentic_compatibility_enabled_684() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT EXISTS(SELECT 1 FROM public.pdc_authenticated_provider_import_agentic_compatibility_controls_684 WHERE singleton AND enabled AND NOT task_enabled AND NOT mailbox_contacted AND NOT uid514_processed AND NOT production_writes) $$;
CREATE FUNCTION public.pdc_monitor_authenticated_uid514_source_scope_684(p_evidence jsonb)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,auth,extensions AS $source$
DECLARE i public.ai_email_intake%rowtype; o public.pdc_provider_email_observations%rowtype; s public.pdc_uid514_attachment_selection_673%rowtype; c public.pdc_authenticated_provider_import_agentic_compatibility_controls_684%rowtype; q uuid; ok boolean:=false;
BEGIN
 IF jsonb_typeof(p_evidence)<>'object' OR p_evidence->>'intake_id' IS DISTINCT FROM '102e286d-1799-4c97-8e45-e0da9fb31c63' OR NOT public.pdc_authenticated_provider_import_agentic_compatibility_enabled_684() OR NOT public.pdc_monitor_authenticated_active_scope_674(p_evidence->>'gateway_instance_id') THEN RETURN false; END IF;
 q:=nullif(p_evidence->>'claim_token','')::uuid;
 SELECT * INTO c FROM public.pdc_authenticated_provider_import_agentic_compatibility_controls_684 WHERE singleton AND enabled;
 SELECT * INTO i FROM public.ai_email_intake WHERE id='102e286d-1799-4c97-8e45-e0da9fb31c63'::uuid AND provider_uid='imap_uid:514' AND status='processing' AND locked_by=auth.uid() AND claim_token=q AND gateway_instance_id=c.gateway_instance_id AND locked_at>=clock_timestamp()-interval '10 minutes' AND lower(source_hash)=lower(p_evidence->>'source_hash') AND coalesce(nullif(btrim(internet_message_id),''),graph_message_id)=p_evidence->>'message_id' AND lower(btrim(sender_email))=lower(btrim(p_evidence->>'sender')) AND received_at=nullif(p_evidence->>'received_at','')::timestamptz AND lower(btrim(recipient_mailbox))=lower(btrim(p_evidence->>'recipient_mailbox')) AND provider_uid=p_evidence->>'provider_uid' AND lower(provider_authserv_id)=lower(p_evidence->>'provider_authserv_id') AND provider_authentication=p_evidence->'provider_authentication';
 SELECT * INTO o FROM public.pdc_provider_email_observations WHERE intake_id=i.id AND attachment_id=(SELECT job_card_attachment_id FROM public.pdc_uid514_attachment_selection_673 WHERE recovery_event_id=25751401 AND intake_id=i.id) AND parent_source_hash=c.parent_source_hash AND provider_message_id=p_evidence->>'message_id' AND provider_authserv_id='mx.google.com' AND authentication=jsonb_build_object('dkim_aligned',false,'dmarc_aligned',true,'gmail_authentication_results',true,'sender_domain','pmgwa.com.au','spf_aligned',true);
 SELECT * INTO s FROM public.pdc_uid514_attachment_selection_673 WHERE recovery_event_id=25751401 AND intake_id=i.id AND parent_source_hash=c.parent_source_hash AND observed_mime_part_count=7 AND retained_authenticated_attachment_count=4 AND all_mime_parts_retained;
 ok:=i.id IS NOT NULL AND o.observation_id IS NOT NULL AND s.selection_id IS NOT NULL AND lower(p_evidence->>'source_hash')=c.parent_source_hash AND p_evidence->>'provider_uid'='imap_uid:514' AND p_evidence->>'recipient_mailbox'=c.mailbox_address AND lower(p_evidence->>'provider_authserv_id')='mx.google.com';
 RETURN ok;
EXCEPTION WHEN others THEN RETURN false;
END $source$;
