CREATE FUNCTION public.attest_pdc_monitor_provider_email_observation_684(p_gateway text,p_claim_token uuid,p_intake_id uuid,p_attachment_id uuid,p_expected_parent_hash text,p_expected_attachment_hash text,p_provider_message_id text,p_provider_authserv_id text,p_authentication jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,auth,extensions AS $attest$
DECLARE v jsonb; i public.ai_email_intake%rowtype; a public.ai_email_attachments%rowtype; e public.pdc_provider_email_observations%rowtype; h text;
BEGIN
 v:=public.pdc_monitor_authenticated_uid514_claim_scope_684(p_gateway,p_claim_token,p_intake_id,p_attachment_id,p_expected_parent_hash,p_expected_attachment_hash); IF v->>'ok'<>'true' THEN RETURN public.navision_backend_response(false,'authenticated_uid514_scope_required'); END IF;
 SELECT * INTO i FROM public.ai_email_intake WHERE id=p_intake_id; SELECT * INTO a FROM public.ai_email_attachments WHERE id=p_attachment_id AND intake_id=p_intake_id;
 IF p_expected_parent_hash<>'440d174b6e1994fbb1afb9c285f068cb62b130f541ebaa834d590f44bdbec280' OR p_expected_attachment_hash<>'9a8f412ec5c9e108817da26b20993fa0a5e61a54f7ac983673c1ef9e2d8af8f4' OR p_provider_authserv_id<>'mx.google.com' OR p_provider_message_id IS DISTINCT FROM coalesce(nullif(btrim(i.internet_message_id),''),i.graph_message_id) OR p_authentication IS DISTINCT FROM i.provider_authentication OR jsonb_typeof(p_authentication)<>'object' OR (SELECT array_agg(k order by k) FROM jsonb_object_keys(p_authentication) k) IS DISTINCT FROM ARRAY['dkim_aligned','dmarc_aligned','gmail_authentication_results','sender_domain','spf_aligned']::text[] OR p_authentication<>jsonb_build_object('dkim_aligned',false,'dmarc_aligned',true,'gmail_authentication_results',true,'sender_domain','pmgwa.com.au','spf_aligned',true) THEN RETURN public.navision_backend_response(false,'provider_observation_binding_mismatch'); END IF;
 h:=encode(extensions.digest(convert_to(jsonb_build_object('contract_version','684.1','intake_id',p_intake_id,'attachment_id',p_attachment_id,'parent_source_hash',p_expected_parent_hash,'attachment_source_hash',p_expected_attachment_hash,'provider_message_id',p_provider_message_id,'provider_authserv_id',p_provider_authserv_id,'authentication',p_authentication)::text,'UTF8'),'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('pdc-provider-email-observation-684:'||p_intake_id::text||':'||p_attachment_id::text,0));
 SELECT * INTO e FROM public.pdc_provider_email_observations WHERE intake_id=p_intake_id AND attachment_id=p_attachment_id;
 IF FOUND THEN IF e.request_sha256<>h THEN RETURN public.navision_backend_response(false,'provider_observation_replay_conflict'); END IF; RETURN public.navision_backend_response(true,'provider_observation_already_attested',jsonb_build_object('observation_id',e.observation_id,'request_sha256',e.request_sha256)); END IF;
 INSERT INTO public.pdc_provider_email_observations(contract_version,intake_id,attachment_id,parent_source_hash,attachment_source_hash,provider_message_id,provider_authserv_id,authentication,request_sha256,attested_by,attested_authority) VALUES('159.2',p_intake_id,p_attachment_id,p_expected_parent_hash,p_expected_attachment_hash,p_provider_message_id,p_provider_authserv_id,p_authentication,h,auth.uid(),'authenticated_provider_684') RETURNING * INTO e;
 RETURN public.navision_backend_response(true,'provider_observation_attested',jsonb_build_object('observation_id',e.observation_id,'request_sha256',e.request_sha256));
END $attest$;
