CREATE FUNCTION public.import_pdc_monitor_jobcard_attachment_authenticated_684(p_gateway text,p_claim_token uuid,p_intake_id uuid,p_attachment_id uuid,p_expected_parent_hash text,p_expected_attachment_hash text,p_authentication jsonb,p_email_vehicle jsonb,p_required_work jsonb,p_operation_lines jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,auth,extensions AS $import$
DECLARE v jsonb; e jsonb; o jsonb; a jsonb; r jsonb;
BEGIN
 v:=public.pdc_monitor_authenticated_uid514_claim_scope_684(p_gateway,p_claim_token,p_intake_id,p_attachment_id,p_expected_parent_hash,p_expected_attachment_hash); IF v->>'ok'<>'true' THEN RETURN public.navision_backend_response(false,'authenticated_uid514_scope_required'); END IF;
 IF p_authentication IS DISTINCT FROM jsonb_build_object('dkim_aligned',false,'dmarc_aligned',true,'gmail_authentication_results',true,'sender_domain','pmgwa.com.au','spf_aligned',true) OR p_email_vehicle->'stock_numbers' IS DISTINCT FROM '["13016925"]'::jsonb OR p_email_vehicle->>'job_card_number' IS DISTINCT FROM 'J139125482' OR p_email_vehicle->'conflicts' IS DISTINCT FROM '[]'::jsonb OR p_email_vehicle->'cancelled' IS DISTINCT FROM 'false'::jsonb OR p_required_work IS DISTINCT FROM '["fabrication","fitting"]'::jsonb OR p_operation_lines IS DISTINCT FROM '[{"source_row_no":1,"operation_no":"OP1","work_key":"owner_supplied_document","description":"Fill Fuel","estimated_hours":0},{"source_row_no":2,"operation_no":"OP2","work_key":"owner_supplied_document","description":"PDI","estimated_hours":0.70},{"source_row_no":3,"operation_no":"OP3","work_key":"fabrication","description":"HDA Tray","estimated_hours":0},{"source_row_no":4,"operation_no":"OP4","work_key":"fitting","description":"Steel Bull Bar","estimated_hours":5.18},{"source_row_no":5,"operation_no":"OP5","work_key":"fitting","description":"Tow Bar long tongue","estimated_hours":1.58}]'::jsonb THEN RETURN public.navision_backend_response(false,'source_layout_or_hours_mismatch',jsonb_build_object('source_total_hours',7.46,'stale_expected_hours_rejected',13.10,'zero_hours_preserved',true,'tow_bar_work_key','fitting')); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.pdc_provider_email_observations WHERE intake_id=p_intake_id AND attachment_id=p_attachment_id AND parent_source_hash=p_expected_parent_hash AND attachment_source_hash=p_expected_attachment_hash AND authentication=p_authentication) THEN RETURN public.navision_backend_response(false,'provider_observation_required_or_mismatch'); END IF;
 e:=jsonb_build_object('authentication',p_authentication,'canonical_attachment_id',p_attachment_id::text,'canonical_document_hash',p_expected_attachment_hash,'contract_version','pmb-email-work-v2','email_vehicle',p_email_vehicle,'operation_lines',p_operation_lines,'required_work',p_required_work);
 r:=public.process_claimed_pdc_email_intake_work(p_intake_id,p_claim_token,p_gateway,p_expected_parent_hash,encode(extensions.digest(convert_to(e::text,'UTF8'),'sha256'),'hex'),e);
 RETURN r;
EXCEPTION WHEN invalid_text_representation THEN RETURN public.navision_backend_response(false,'invalid_authenticated_uid514_payload');
END $import$;
