BEGIN
 v:=public.pdc_monitor_authenticated_uid514_claim_scope_684(p_gateway,p_claim_token,p_intake_id,p_attachment_id,p_expected_parent_hash,p_expected_attachment_hash); IF v->>'ok'<>'true' THEN RETURN public.navision_backend_response(false,'authenticated_uid514_scope_required'); END IF;
 r:=public.read_pdc_jobcard_attachment_import_receipt(p_receipt_id);
 IF r->>'ok'<>'true' OR r#>>'{data,intake_id}' IS DISTINCT FROM p_intake_id::text OR r#>>'{data,attachment_id}' IS DISTINCT FROM p_attachment_id::text OR r#>>'{data,parent_source_hash}' IS DISTINCT FROM p_expected_parent_hash OR r#>>'{data,attachment_source_hash}' IS DISTINCT FROM p_expected_attachment_hash THEN RETURN public.navision_backend_response(false,'canonical_receipt_binding_mismatch'); END IF;
 RETURN r;
END $read$;
