CREATE OR REPLACE FUNCTION public.pdc_agentic_email_source_authorized_502(p_evidence jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,extensions AS $source_compat$
BEGIN
 IF p_evidence->>'intake_id'='102e286d-1799-4c97-8e45-e0da9fb31c63' THEN RETURN public.pdc_monitor_authenticated_uid514_source_scope_684(p_evidence); END IF;
 RETURN (SELECT public.pdc_email_monitor_runtime_authorized_502(p_evidence->>'gateway_instance_id') AND jsonb_typeof(p_evidence)='object' AND EXISTS(SELECT 1 FROM public.ai_email_intake i JOIN public.monitored_mailboxes m ON m.id=i.monitored_mailbox_id AND m.active JOIN public.pdc_provider_email_observations o ON o.intake_id=i.id WHERE i.id=nullif(p_evidence->>'intake_id','')::uuid AND i.status='processing' AND i.locked_by=auth.uid() AND i.claim_token=nullif(p_evidence->>'claim_token','')::uuid AND i.gateway_instance_id=p_evidence->>'gateway_instance_id' AND i.locked_at>=clock_timestamp()-interval '10 minutes' AND lower(i.source_hash)=lower(p_evidence->>'source_hash') AND coalesce(nullif(btrim(i.internet_message_id),''),i.graph_message_id)=p_evidence->>'message_id' AND lower(btrim(i.sender_email))=lower(btrim(p_evidence->>'sender')) AND i.received_at=nullif(p_evidence->>'received_at','')::timestamptz AND lower(btrim(i.recipient_mailbox))=lower(btrim(m.mailbox_address)) AND lower(btrim(i.recipient_mailbox))=lower(btrim(p_evidence->>'recipient_mailbox')) AND coalesce(i.provider_uid,'')=coalesce(p_evidence->>'provider_uid','') AND lower(coalesce(i.provider_authserv_id,''))=lower(coalesce(p_evidence->>'provider_authserv_id','')) AND coalesce(i.provider_authentication,'{}'::jsonb)=coalesce(p_evidence->'provider_authentication','{}'::jsonb) AND o.parent_source_hash=lower(p_evidence->>'source_hash') AND o.provider_message_id=p_evidence->>'message_id' AND lower(o.provider_authserv_id)='mx.google.com' AND o.authentication->'gmail_authentication_results'='true'::jsonb AND (o.authentication->'spf_aligned'='true'::jsonb OR o.authentication->'dkim_aligned'='true'::jsonb OR o.authentication->'dmarc_aligned'='true'::jsonb) AND lower(o.authentication->>'sender_domain')=split_part(lower(btrim(i.sender_email)),'@',2) AND EXISTS(SELECT 1 FROM public.pdc_monitor_exact_sender_enrollments e WHERE e.active AND e.sender_sha256=encode(extensions.digest(convert_to(lower(btrim(i.sender_email)),'UTF8'),'sha256'),'hex'))));
EXCEPTION WHEN others THEN RETURN false;
END $source_compat$;
