GRANT EXECUTE ON FUNCTION public.pdc_agentic_email_source_authorized_502(jsonb) TO authenticated;

CREATE FUNCTION public.admin_rollback_pdc_authenticated_provider_import_agentic_compatibility_684(p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,auth AS $rollback$
DECLARE r public.pdc_authenticated_provider_import_agentic_compatibility_controls_684%rowtype; k text:=encode(extensions.digest(convert_to('pdc-staging-684-rollback|'||btrim(coalesce(p_reason,'')),'UTF8'),'sha256'),'hex');
BEGIN
 IF NOT public.pdc_monitor_staging_guard() OR auth.role()<>'authenticated' OR NOT EXISTS(SELECT 1 FROM public.pdc_user_roles u WHERE u.auth_user_id=auth.uid() AND u.active AND u.account_status='approved' AND u.role::text='administrator') THEN RAISE EXCEPTION 'PDC_684_ADMIN_ROLLBACK_REQUIRED' USING errcode='42501'; END IF;
 SELECT * INTO r FROM public.pdc_authenticated_provider_import_agentic_compatibility_controls_684 WHERE singleton FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'PDC_684_CONTROL_MISSING' USING errcode='55000'; END IF;
 IF NOT r.enabled THEN RETURN jsonb_build_object('ok',true,'code','compatibility_rollback_replayed'); END IF;
