 INSERT INTO public.pdc_authenticated_provider_import_agentic_compatibility_history_684(event_key,event_kind,predecessor_head,successor_head,actor_id,actor_email,jwt_role,server_application_role,gateway_instance_id,release_name,source_sha,manifest_sha256,planner_sha256,trust_receipt_sha256,recovery_event_id,parent_source_hash,before_state,after_state,predecessor_function_hashes,successor_function_hashes,source_total_hours,stale_expected_hours,task_enabled,mailbox_contacted,uid514_processed,production_writes,rollback_contract) VALUES(k,'rollback','20260828040000','20260828050000',r.actor_id,r.actor_email,r.jwt_role,r.server_application_role,r.gateway_instance_id,r.release_name,r.source_sha,r.manifest_sha256,r.planner_sha256,r.trust_receipt_sha256,r.recovery_event_id,r.parent_source_hash,to_jsonb(r),to_jsonb((SELECT c FROM public.pdc_authenticated_provider_import_agentic_compatibility_controls_684 c WHERE singleton)),jsonb_build_object('reason',p_reason),jsonb_build_object('reason',p_reason),7.46,13.10,false,false,false,false,'Administrator-only disable; no history or evidence deletion');
 RETURN jsonb_build_object('ok',true,'code','compatibility_rollback_applied');
