SELECT encode(extensions.digest(convert_to('pdc-staging-684-forward|20260828050000','UTF8'),'sha256'),'hex'),'forward_compatibility','20260828040000','20260828050000',c.actor_id,c.actor_email,c.jwt_role,c.server_application_role,c.gateway_instance_id,c.release_name,c.source_sha,c.manifest_sha256,c.planner_sha256,c.trust_receipt_sha256,c.recovery_event_id,c.parent_source_hash,jsonb_build_object('provider_observations',0,'uid514_status','failed','queue_attempts',8,'stale_import_wrapper','monitor_scope_required','agentic_dkim_requirement','true'),jsonb_build_object('claim_bound_provider_observation','authenticated_provider_684','source_total_hours',7.46,'stale_expected_hours_rejected',13.10,'zero_hours_preserved',true,'tow_bar_work_key','fitting','task_enabled',false,'mailbox_contacted',false,'uid514_processed',false,'production_writes',false),jsonb_build_object('pdc_monitor_actor_scope','fbdada6560ea401c0ba4f721eada6353225398df24e851be041fad58c4699b08','attest_provider','7be3241ac65da67024907c2afd1f47d3d82ca429960d3f1464dc56d489c8e0dd','import_wrapper','ac656b019e863fba781e2280655cba2a9f8a00ae432939699839a1d902508266','read_wrapper','695bb6dedcad700ac81c221f14cf9607707417691f27df58a0a5fbb42c10c1fa','agentic_source','55161035e5ec36c10d2df3b84ec85f937d9287c55163f87d7f4d2335d24b3f79'),jsonb_build_object('successor','computed_after_install'),7.46,13.10,false,false,false,false,'Administrator-only disable; immutable history; no destructive rollback'
