INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260828050000','684_authenticated_provider_import_agentic_compatibility',ARRAY['Exact 683 and unrelated 714-716 predecessor/source guards with staging-only sentinel and Production absence','Claim-bound exact authenticated actor provider observation for retained UID514 Job Card attachment only; no generic observation creation','Authenticated canonical import/readback wrappers prove actor, importer, writer, gateway, release, source, manifest, planner, trust, mailbox, claim and source hashes server-side','Agentic context, plan, action, apply and finalize wrappers use the exact retained source proof and accept the genuine SPF/DMARC-aligned five-key Gmail object with DKIM=false','Preserve UID514 intake, authorization, selection, seven attachments, four extractions and all prior claim attempts; idempotent observation/import replay','Use exact PDF layout rows OP1 Fill Fuel 0.00, OP2 PDI 0.70, OP3 HDA Tray 0.00, OP4 Steel Bull Bar 5.18, OP5 Tow Bar long tongue 1.58; source total 7.46; reject stale 13.10; map Tow Bar to fitting','Immutable forced-RLS history and Administrator-only disable; no task enablement, mailbox contact, UID514 processing, evidence deletion or Production action']);
